class TtitraceEvent(object):
    """
    TTI trace event.

    See `Annex 11.2.1 in 5G Uplane Software Architecture
    <https://5gwebserver.eecloud.dynamic.nsn-net.net/CinqG/uplaneSwDoc/docGen/doc/itf/Events.html>`_.

    Usage:

    * Read a file with UDP binary data for TTI events in streaming mode and handle each event

            Code::

                file_name = '/tmp/ttitrace_streaming.udp'
                multi_base_folder = '/tmp/generated_tti_trace'

                with open(file_name, 'rb') as file_obj:
                    for event in TtitraceReader(
                            multi_base_folder=multi_base_folder,
                            file_obj=file_obj)):
                        # handle event

    * Check the TTI event type and print the event data

        Code::

            if event.type == "ttiStartInd":
                print(event.data)

        Output::

            {'currentSlot': 61, 'currentSfn': 61}

    * Pretty print the event data

        Code::

            import json

            if event.type == "ulFdSchedData":
                print(json.dumps(event.data, indent=4))

        Output::

            {
                "beamId": 0,
                "csiTriggerId": 0,
                "tbSize": 3752,
                "K2": 6,
                "redundancyVersion": 0,
                "ueData": {
                    "flag": 0,
                    "reScaledCorrAvgSinr": 26.665475845336914,
                    "ulMimoMode": 20,
                    "currentUeDataRate": 13322.0
                },
                "isValidWhatIsProposed": 1,
                "onAirTimeSlot": 24,
                "startPrb": 0,
                "numOfPrb": 66,
                "PMI": 0,
                "rrmUlProposedMcs": 28,
                "txNumber": 1,
                "rrmMaxNumPrbUl": 66,
                "cellDbIndex": 0,
                "SLIV": 55,
                "onAirTimeSfn": 64,
                "antPort": 49152,
                "ulHarqProcessIndex": 5,
                "commonIdentifier": {
                    "rnti": 10957,
                    "physCellId": 50
                },
                "rrmUlUsedMcs": 0,
                "rrmBufferedDataUlTotal_bytes": 0,
                "ulHarqBufferIndex": 2,
                "numOfLayers": 2,
                "isDefaultMcsProposed": 0
            }


    * Access an TTI event parameter via event.data

        Code::

                print(event.data["ueData"]["ulMimoMode"])

        Output::

            20

    * Simplified access to an TTI event parameter via event[...]

        Code::

                print(event["ulMimoMode"])

        Output::

            20
    """
    def __init__(self, event_data):
        """
        Create a TtitraceEvent.

        A TtitraceEvent wraps a decoded TTI trace event, represented as a nested dict in event.data.
        It offers easy access methods like event.type and event[key].

        :param dict event_data:  a decoded event (nested dictionary)
        """
        self._event_data = event_data

    def __getitem__(self, key_name):
        """
        Return the field value for a field name, that occurs anywhere in the nested event data dictionaries.

        :param str key_name:    key name of an event field
        :return:            return the value for the key
        """
        return _get_value_from_key(
            event_data=self._event_data,
            key_name=key_name)

    def _get_type(self):
        """
        Return the type of the event.
        """
        event_type = self._event_data['discriminator']
        return event_type

    def _get_event_data_body(self):
        """
        Return body of event payload.
        """
        return self._event_data['payload'][self.type]['body']

    type = property(_get_type)
    data = property(_get_event_data_body)


def _get_value_from_key(event_data, key_name):
    """
    Get field value for a field name.

    The field name can occur anywhere in the nested dictionaries of the event data and is recursively searched for.

    :param dict event_data:      decoded event data (dictionary)
    :param str key_name:        name of a field within the event data
    :return:                value for the key
    """
    for key, value in event_data.items():
        if key == key_name:
            return value
        if isinstance(value, dict):
            result = _get_value_from_key(
                event_data=value,
                key_name=key_name)
            if result is not None:
                return result
